REVISION_WORKFLOW_ID = "e1000000-0000-4000-8000-000000000010"
MAX_REVISIONS = 3


def run(state, draft, requests):
    config = state.get("config") or {}

    return {
        "needs_revision": len(requests) > 0,
        "settings": {
            "workflow_id": config.get("revision_workflow_id", REVISION_WORKFLOW_ID),
            "max_iterations": config.get("max_revisions", MAX_REVISIONS),
            "state": {
                "chapter": draft,
                "requests": requests,
                "context": state.get("story"),
            },
        },
        "chapter": draft,
    }
